<template><div><template v-if="isStudent"><AppPageHeader eyebrow="Conquistas" title="Meus Certificados" description="Documentos verificáveis, com validade, versão e código público de autenticação."/><div v-if="loading" class="grid grid-cols-1 gap-5 md:grid-cols-2"><div v-for="i in 2" :key="i" class="h-80 animate-pulse rounded-2xl bg-white/70"/></div><div v-else-if="loadError" class="premium-card p-8 text-center" data-testid="certificates-error"><p class="font-bold text-red-700">Não foi possível carregar seus certificados.</p><button @click="loadMyCertificates" class="mt-4 rounded-xl bg-red-600 px-4 py-2 text-sm font-bold text-white">Tentar novamente</button></div><EmptyState v-else-if="myCertificates.length===0" icon="🏆" title="Você ainda não possui certificados." description="Conclua os requisitos dos seus cursos para liberar seus certificados."><router-link to="/dashboard" class="inline-flex items-center rounded-xl px-4 py-2.5 text-sm font-bold text-white" :style="{background:'var(--brand-primary)'}">Ver meus cursos</router-link></EmptyState><div v-else class="space-y-6"><div class="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3"><CertificateCard v-for="cert in myCertificates" :key="cert.id" :certificate="cert" :test-id="'student-cert-'+cert.id"/></div><div class="premium-card flex flex-col items-center justify-between gap-3 p-4 text-center sm:flex-row sm:text-left"><div><p class="text-sm font-bold text-slate-800">Precisa verificar outro documento?</p><p class="mt-0.5 text-xs text-slate-400">A validação pública pode ser feita sem login.</p></div><router-link to="/validar-certificado" class="text-sm font-bold text-[var(--brand-primary)]">Validar outro certificado →</router-link></div></div></template>
<template v-else-if="isAdmin"><AppPageHeader eyebrow="Certificação" title="Certificados" description="Emita novos certificados e consulte registros. Revogação e reemissão são feitas pelo lifecycle confiável."><template #actions><router-link to="/operations/certificates" class="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 shadow-sm"><NavIcon name="shield"/>Certificados confiáveis</router-link><AppButton @click="showForm=true" data-testid="new-certificate-btn">+ Novo certificado</AppButton></template></AppPageHeader><AppCard v-if="showForm" class="mb-6"><template #header><p class="font-bold text-slate-900">Gerar certificado</p></template><form @submit.prevent="saveCertificate" class="space-y-4"><div><label class="mb-2 block text-sm font-semibold text-slate-700">Matrícula concluída *</label><select v-model="form.enrollment_id" class="w-full" required><option value="">Selecione uma matrícula</option><option v-for="enrollment in completedEnrollments" :key="enrollment.id" :value="enrollment.id">{{ getStudentCpfById(enrollment.student_id) }} - {{ getClassNameById(enrollment.class_id) }}</option></select></div><div class="flex gap-2"><AppButton type="submit" :disabled="saving" data-testid="generate-certificate-btn">{{ saving?'Gerando...':'Gerar certificado' }}</AppButton><AppButton type="button" variant="secondary" @click="showForm=false" data-testid="cancel-certificate-btn">Cancelar</AppButton></div></form></AppCard><AppCard class="mb-6"><template #header><div><p class="premium-kicker">Validação</p><h2 class="mt-1 font-bold text-slate-900">Consultar autenticidade</h2></div></template><div class="flex flex-col gap-3 sm:flex-row sm:items-end"><AppInput v-model="validationCode" label="Código de validação" placeholder="XXXX-XXXX-XXXX-XXXX" class="flex-1"/><AppButton @click="validateCertificate" data-testid="validate-certificate-btn">Validar</AppButton></div><AppAlert v-if="validationError" type="error" class="mt-4" closable @close="validationError=''">{{ validationError }}</AppAlert><div v-if="validationResult" class="mt-4 rounded-2xl border p-4 text-sm" :class="validationResult.valid?'border-emerald-200 bg-emerald-50 text-emerald-800':'border-red-200 bg-red-50 text-red-800'"><template v-if="validationResult.valid"><p class="font-bold">✓ Certificado válido</p><p class="mt-2 leading-6">Número: {{ validationResult.certificate_number }}<br>Aluno: {{ validationResult.student_name }}<br>Curso: {{ validationResult.course_name }}<br>Emitido em: {{ formatDate(validationResult.issued_at) }}</p></template><p v-else class="font-bold">✗ Certificado inválido</p></div></AppCard><LoadingState v-if="loading" message="Carregando certificados..."/><AppAlert v-else-if="loadError" type="error" class="mb-6" closable @close="loadError=''">{{ loadError }}</AppAlert><EmptyState v-else-if="adminCertificates.length===0" title="Nenhum certificado emitido" description="Certificados aparecerão aqui após a conclusão de cursos."/><div v-else class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="cert in adminCertificates" :key="cert.id" class="premium-card p-5"><div class="flex items-start gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700"><NavIcon name="shield"/></span><div class="min-w-0"><p class="truncate font-bold text-slate-900">{{ getStudentCpfByEnrollment(cert) }}</p><p class="mt-1 text-xs text-slate-400">{{ getClassNameByEnrollment(cert.enrollment_id) }}</p></div></div><dl class="mt-4 space-y-2 text-xs"><div class="flex justify-between gap-3"><dt class="text-slate-400">Número</dt><dd class="font-semibold text-slate-700">{{ cert.certificate_number }}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-400">Versão</dt><dd class="font-semibold text-slate-700">v{{ cert.version||1 }}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-400">Emissão</dt><dd class="font-semibold text-slate-700">{{ formatDate(cert.issued_at) }}</dd></div></dl><code class="mt-4 block truncate rounded-xl bg-slate-50 p-3 text-xs text-slate-600">{{ cert.validation_code }}</code></article></div></template></div></template>
<script setup>import{ref,onMounted,computed}from'vue';import{useAuthStore}from'../stores/auth';import api from'../api/client';import{fetchMyCertificates}from'../api/certificates';import AppPageHeader from'../components/AppPageHeader.vue';import AppCard from'../components/AppCard.vue';import AppButton from'../components/AppButton.vue';import AppInput from'../components/AppInput.vue';import AppAlert from'../components/AppAlert.vue';import EmptyState from'../components/EmptyState.vue';import LoadingState from'../components/LoadingState.vue';import CertificateCard from'../components/CertificateCard.vue';import NavIcon from'../components/NavIcon.vue';import{useToast}from'../composables/useToast';const{error:toastError}=useToast(),authStore=useAuthStore();const isAdmin=computed(()=>['admin','super_admin'].includes(authStore.userRole?.toLowerCase())),isStudent=computed(()=>authStore.userRole?.toLowerCase()==='student');const myCertificates=ref([]),loading=ref(false),loadError=ref('');const loadMyCertificates=async()=>{loading.value=true;loadError.value='';try{myCertificates.value=(await fetchMyCertificates()).data}catch{loadError.value='Não foi possível carregar seus certificados.'}finally{loading.value=false}};const adminCertificates=ref([]),enrollments=ref([]),students=ref([]),classes=ref([]),courses=ref([]),showForm=ref(false),form=ref({enrollment_id:''}),validationCode=ref(''),validationResult=ref(null),saving=ref(false),validationError=ref('');const completedEnrollments=computed(()=>enrollments.value.filter(e=>e.status==='CONCLUIDA'));const formatDate=d=>new Date(d).toLocaleDateString('pt-BR');const getStudentCpfById=id=>students.value.find(s=>s.id===id)?.cpf||'Aluno desconhecido';const getCourseNameById=id=>courses.value.find(c=>c.id===id)?.name||'Curso desconhecido';const getClassNameById=id=>{const c=classes.value.find(x=>x.id===id);return c?`${getCourseNameById(c.course_id)} - ${formatDate(c.start_date)}`:'Turma desconhecida'};const getStudentCpfByEnrollment=cert=>{const e=enrollments.value.find(x=>x.id===cert.enrollment_id);return e?getStudentCpfById(e.student_id):'Desconhecido'};const getClassNameByEnrollment=id=>{const e=enrollments.value.find(x=>x.id===id);return e?getClassNameById(e.class_id):'Curso desconhecido'};const loadAdminCertificates=async()=>{loading.value=true;loadError.value='';try{adminCertificates.value=(await api.get('/api/v1/certificates/')).data}catch{loadError.value='Erro ao carregar certificados. Tente novamente.'}finally{loading.value=false}};const loadDependencies=async()=>{try{const[e,s,c,co]=await Promise.all([api.get('/api/v1/enrollments/'),api.get('/api/v1/students/'),api.get('/api/v1/classes/'),api.get('/api/v1/courses/')]);enrollments.value=e.data;students.value=s.data;classes.value=c.data;courses.value=co.data}catch{/* dependency load failure — dropdowns stay empty */}};const saveCertificate=async()=>{saving.value=true;try{await api.post('/api/v1/certificates/',form.value);form.value={enrollment_id:''};showForm.value=false;loadAdminCertificates()}catch(error){toastError('Erro ao gerar certificado: '+(error.response?.data?.detail||error.message))}finally{saving.value=false}};const validateCertificate=async()=>{validationError.value='';validationResult.value=null;try{validationResult.value=(await api.post('/api/v1/certificates/validate',{validation_code:validationCode.value})).data}catch(error){if(error.response?.status===404)validationResult.value={valid:false};else validationError.value='Erro ao validar certificado. Verifique sua conexão e tente novamente.'}};onMounted(async()=>{await authStore.initializeUser();if(isStudent.value)loadMyCertificates();else if(isAdmin.value){loadDependencies();loadAdminCertificates()}})</script>
